using LedgerFlow.Api.Models;using Microsoft.EntityFrameworkCore;namespace LedgerFlow.Api.Data;public static class SeedData{public static async Task EnsureSeededAsync(AppDbContext db,CancellationToken ct=default){await db.Database.EnsureCreatedAsync(ct);if(await db.Transactions.AnyAsync(ct))return;var now=DateTimeOffset.UtcNow;db.Transactions.AddRange(new Transaction{Reference="SET-2026-1042",Account="OPS-10021",Amount=18450.22m,Currency="CAD",BookedAt=now.AddMinutes(-18),Status=TransactionStatus.Matched,Reason="Passed deterministic reconciliation checks."},new Transaction{Reference="SET-2026-1043",Account="OPS-10410",Amount=930m,Currency="CAD",BookedAt=now.AddMinutes(-12),Status=TransactionStatus.Exception,Reason="Account identifier requires review."},new Transaction{Reference="SET-2026-1044",Account="OPS-12008",Amount=74200.14m,Currency="CAD",BookedAt=now.AddMinutes(-6),Status=TransactionStatus.Pending});await db.SaveChangesAsync(ct);}}
